script:
var doc = Document;
// Goal: a new sheet carrying the requested title block, with a floor plan placed on it.

// 1. Candidate views: the document's non-template floor plans. A view can sit on one sheet only,
//    so step 4 asks Viewport.CanAddViewToSheet per candidate and duplicates one when every plan is
//    already placed -- no new level or plan is created for the sheet.
var candidates = new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId>();
foreach (Autodesk.Revit.DB.ViewPlan v in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ViewPlan))) {
  if (!v.IsTemplate && v.ViewType == Autodesk.Revit.DB.ViewType.FloorPlan) candidates.Add(v.Id);
}
if (candidates.Count == 0) throw new System.Exception("no floor plan to place; create one with ViewPlan.Create (levels-grids-and-plan-views)");

// 2. The title block TYPE: a FamilySymbol in OST_TitleBlocks. Which ones exist depends on the
//    template; pick by name when the user named one, else the first. An absent title block family
//    must be loaded first (family-document-build-load-place shows LoadFamily).
Autodesk.Revit.DB.FamilySymbol tbType = null;
foreach (Autodesk.Revit.DB.FamilySymbol s in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.FamilySymbol)).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_TitleBlocks)) { tbType = s; break; }
var tbTypeId = tbType != null ? tbType.Id : Autodesk.Revit.DB.ElementId.InvalidElementId;

return Connector.WithTransaction(doc, () => {
  // 3. Create the sheet WITH the title block type. Activate the symbol first if it has never been
  //    placed. Passing ElementId.InvalidElementId makes a sheet with no title block. SheetNumber
  //    must be unique in the document.
  if (tbType != null && !tbType.IsActive) { tbType.Activate(); }
  var sheet = Autodesk.Revit.DB.ViewSheet.Create(doc, tbTypeId);
  sheet.SheetNumber = "H-" + (System.DateTime.UtcNow.Ticks % 100000000);
  sheet.Name = "How-to plan";

  // 4. Ask before placing: CanAddViewToSheet is false for a view already on any sheet (and for
  //    schedules/legends, which have their own placement API); Viewport.Create throws otherwise.
  //    Take the first placeable plan; if all are placed, duplicate one (View.Duplicate) -- a
  //    duplicate is a new view and is placeable.
  Autodesk.Revit.DB.ElementId planId = null;
  bool duplicated = false;
  foreach (var cid in candidates) {
    if (Autodesk.Revit.DB.Viewport.CanAddViewToSheet(doc, sheet.Id, cid)) { planId = cid; break; }
  }
  if (planId == null) {
    planId = (doc.GetElement(candidates[0]) as Autodesk.Revit.DB.View).Duplicate(Autodesk.Revit.DB.ViewDuplicateOption.Duplicate);
    duplicated = true;
  }
  var plan = doc.GetElement(planId) as Autodesk.Revit.DB.View;
  var viewport = Autodesk.Revit.DB.Viewport.Create(doc, sheet.Id, plan.Id, new Autodesk.Revit.DB.XYZ(1, 1, 0));
  doc.Regenerate();

  // 5. Verify: the plan is among the sheet's placed views, and the title block instance on the
  //    sheet is the requested type. To CHANGE a sheet's title block later, create a new sheet with
  //    the right type and move the viewports: setting SheetTitleBlockId on a live sheet crashes Revit.
  var placed = sheet.GetAllPlacedViews();
  Autodesk.Revit.DB.Element tbInstance = null;
  foreach (var e in new Autodesk.Revit.DB.FilteredElementCollector(doc, sheet.Id).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_TitleBlocks)) { tbInstance = e; break; }
  var canAddAgain = Autodesk.Revit.DB.Viewport.CanAddViewToSheet(doc, sheet.Id, plan.Id);
  return new { sheetId = sheet.Id.Value, sheetNumber = sheet.SheetNumber, titleBlockType = tbType != null ? tbType.Name : "(none loaded)", planName = plan.Name, planDuplicated = duplicated, planPlaced = placed.Contains(plan.Id), viewportId = viewport.Id.Value, titleBlockMatches = tbInstance != null && tbInstance.GetTypeId() == tbTypeId, viewPlaceableTwice = canAddAgain };
});
